page_settings.custom_css:
@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@200;300;400;500;600;700;800&family=Inter:wght@300;400;500;600&display=swap');

body,.elementor-page{background:#0c0b09!important;}
.elementor-section-wrap{background:#0c0b09;}
*{box-sizing:border-box;}

/* ── HERO ───────────────────────────────────── */
.at-hero-section{overflow:hidden;}
.at-hero-section .swiper,
.at-hero-section .swiper-container,
.at-hero-section .elementor-slides-wrapper,
.at-hero-section .elementor-main-swiper{height:920px!important;}
.at-hero-section .swiper-slide{align-items:flex-end!important;}
.at-hero-section .elementor-slide-inner{
  width:100%!important;padding:0 72px 80px 72px!important;
  align-items:flex-start!important;text-align:left!important;flex-direction:column;}
.at-hero-section .elementor-slide-content{text-align:left!important;max-width:1100px;}
.at-hero-section .elementor-slide-heading{
  font-family:'Manrope',sans-serif!important;font-weight:200!important;
  font-size:88px!important;line-height:0.98!important;
  letter-spacing:-0.035em!important;color:#ebe3d2!important;
  margin:0 0 32px!important;white-space:pre-line;}
.at-hero-section .elementor-slide-heading em{
  font-style:normal;font-weight:500;color:#c9a25f;}
.at-hero-section .elementor-slide-heading .at-ey{
  display:block;font-family:'Manrope',sans-serif!important;
  font-weight:500!important;font-size:11px!important;
  letter-spacing:0.22em!important;text-transform:uppercase;
  color:#c9a25f;margin-bottom:28px;line-height:1.4;}
.at-hero-section .elementor-slide-heading .at-ey::before{
  content:'';display:inline-block;width:36px;height:1px;
  background:#c9a25f;vertical-align:middle;margin-right:14px;}
.at-hero-section .elementor-slide-description{
  font-family:'Inter',sans-serif!important;font-size:18px!important;
  line-height:1.6!important;color:#c8bfac!important;
  max-width:540px;margin:0 0 44px!important;}
.at-hero-section .elementor-slide-button{
  background:transparent!important;border:1px solid #c9a25f!important;
  color:#ebe3d2!important;font-family:'Manrope',sans-serif!important;
  font-weight:500!important;font-size:13px!important;
  letter-spacing:0.18em!important;text-transform:uppercase!important;
  padding:18px 30px!important;border-radius:0!important;
  transition:background .4s,color .3s!important;}
.at-hero-section .elementor-slide-button:hover{
  background:#c9a25f!important;color:#0c0b09!important;}
.at-hero-section .swiper-pagination{
  bottom:80px!important;right:72px!important;
  left:auto!important;width:auto!important;text-align:right;}
.at-hero-section .swiper-pagination-bullet{
  width:8px;height:8px;border-radius:50%;
  border:1px solid #8c8473;background:transparent;opacity:1;margin:0 5px!important;}
.at-hero-section .swiper-pagination-bullet-active{
  background:#c9a25f!important;border-color:#c9a25f!important;}

/* ── MANIFESTO watermark ────────────────────── */
.at-manifesto-section{overflow:hidden;}
.at-manifesto-section>.elementor-container::after{
  content:'MANBAU';position:absolute;right:-60px;top:50%;
  transform:translateY(-50%);font-family:'Manrope',sans-serif;
  font-weight:200;font-size:320px;color:#ebe3d2;opacity:.025;
  letter-spacing:-0.06em;pointer-events:none;z-index:0;}

/* ── FIGURES ────────────────────────────────── */
.at-figures-col+.at-figures-col>.elementor-element-populated{
  border-left:1px solid rgba(235,227,210,.12)!important;}
.at-figures-section .elementor-column>.elementor-element-populated{
  border-top:1px solid rgba(235,227,210,.12);
  padding:56px 40px 56px!important;}
.at-figures-section .elementor-column:first-child>.elementor-element-populated{
  padding-left:0!important;}
.at-figures-section .elementor-counter-number-wrapper{
  font-family:'Manrope',sans-serif;font-weight:200;letter-spacing:-0.05em;}
.at-figures-section .elementor-counter-title{
  font-family:'Manrope',sans-serif;font-weight:400;}

/* ── SERVICE CARDS ──────────────────────────── */
.at-svc-row>.elementor-container{gap:24px!important;}
.at-svc-row .elementor-row{gap:24px!important;}
.at-svc-col{position:relative;overflow:hidden;cursor:pointer;}
.at-svc-col .elementor-background-overlay{
  background:linear-gradient(
    to bottom,
    rgba(12,11,9,.06) 0%,
    rgba(12,11,9,.35) 40%,
    rgba(12,11,9,.92) 76%,
    rgba(12,11,9,.97) 100%
  )!important;opacity:1!important;transition:opacity .8s;}
.at-svc-col>.elementor-element-populated{display:flex!important;flex-direction:column!important;}
.at-svc-col>.elementor-element-populated>.elementor-widget-wrap{
  display:flex!important;flex-direction:column!important;
  justify-content:space-between!important;
  min-height:520px;height:100%;
  padding:28px 32px 36px!important;}
.at-svc-col .at-svc-tag p{
  font-family:'Manrope',sans-serif!important;font-weight:500!important;
  font-size:12px!important;letter-spacing:0.2em!important;text-transform:uppercase;
  color:#c9a25f!important;margin:0;}
.at-svc-col .at-svc-title .elementor-heading-title{
  font-family:'Manrope',sans-serif!important;font-weight:300!important;
  font-size:36px!important;letter-spacing:-0.025em!important;
  line-height:1.05!important;color:#ebe3d2!important;margin:0!important;}
.at-svc-col .at-svc-desc .elementor-text-editor{
  max-height:0;overflow:hidden;opacity:0;
  transition:max-height .5s cubic-bezier(.2,.7,.2,1),opacity .4s ease;
  font-size:14px;line-height:1.55;color:#c8bfac;}
.at-svc-col:hover .at-svc-desc .elementor-text-editor{max-height:160px;opacity:1;}
.at-svc-col .at-svc-arrow .elementor-button-wrapper{display:flex;justify-content:flex-end;}
.at-svc-col .at-svc-arrow .elementor-button{
  width:44px!important;height:44px!important;padding:0!important;
  border-radius:50%!important;border:1px solid #8c8473!important;
  background:rgba(12,11,9,.4)!important;color:#ebe3d2!important;
  display:inline-flex!important;align-items:center!important;justify-content:center!important;
  font-size:16px!important;transition:all .3s!important;}
.at-svc-col:hover .at-svc-arrow .elementor-button{
  background:#c9a25f!important;border-color:#c9a25f!important;color:#0c0b09!important;}

/* ── PILLARS ─────────────────────────────────── */
.at-pillars-section .at-pillar-col>.elementor-element-populated{
  border-top:1px solid rgba(235,227,210,.12)!important;
  padding:48px 32px 48px!important;}
.at-pillars-section .at-pillar-col+.at-pillar-col>.elementor-element-populated{
  border-left:1px solid rgba(235,227,210,.12)!important;}
.at-pillars-section .at-pillar-col:first-child>.elementor-element-populated{
  padding-left:0!important;}
.at-pillar-num p{
  font-family:'Manrope',sans-serif!important;font-weight:500!important;
  font-size:14px!important;letter-spacing:0.2em!important;color:#c9a25f!important;margin:0;}

/* ── CTA glows ──────────────────────────────── */
.at-cta-section{position:relative;}
.at-cta-section::before{
  content:'';position:absolute;inset:0;pointer-events:none;z-index:0;
  background:radial-gradient(circle at 18% 38%,rgba(201,162,95,.10),transparent 50%),
             radial-gradient(circle at 82% 70%,rgba(201,162,95,.06),transparent 55%);}
.at-cta-section>.elementor-container{position:relative;z-index:1;}
.at-cta-section .at-contact-link a{
  color:#ebe3d2!important;text-decoration:none;
  border-bottom:1px solid rgba(235,227,210,.12);padding-bottom:8px;
  display:inline-flex;align-items:center;justify-content:space-between;
  gap:16px;width:100%;font-family:'Manrope',sans-serif;
  font-weight:300;font-size:28px;letter-spacing:-0.02em;
  transition:color .3s,border-color .3s;}
.at-cta-section .at-contact-link a:hover{color:#c9a25f!important;border-color:#c9a25f!important;}

/* ── FOOTER ─────────────────────────────────── */
.at-footer-section .elementor-icon-list-icon,
.at-footer-bottom-section .elementor-icon-list-icon{display:none!important;}
.at-footer-section .elementor-icon-list-item,
.at-footer-bottom-section .elementor-icon-list-item{padding-left:0!important;}
.at-footer-section .elementor-icon-list-text a{
  color:#8c8473;text-decoration:none;transition:color .2s;}
.at-footer-section .elementor-icon-list-text a:hover{color:#c9a25f;}
.at-footer-bottom-section .elementor-icon-list-items{
  display:flex;flex-direction:row;gap:24px;}
.at-footer-bottom-section .elementor-icon-list-text a{
  color:#8c8473;text-decoration:none;font-size:12px;}
.at-footer-bottom-section .elementor-icon-list-text a:hover{color:#c9a25f;}

/* ── Eyebrow dividers ───────────────────────── */
.at-eyebrow-widget .elementor-heading-title{
  font-family:'Manrope',sans-serif!important;font-weight:500!important;
  font-size:11px!important;letter-spacing:0.22em!important;
  text-transform:uppercase!important;color:#c9a25f!important;}
